{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Vismodegib, the highest-transfer analogue (0.8506), has a measured absolute oral bioavailability of 31.8% in healthy subjects after a 150 mg dose despite being poorly soluble and lipophilic, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Erlotinib, a structurally related lipophilic heteroaromatic kinase inhibitor, has an absolute oral bioavailability of 76% in cancer patients, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C78"],
      "claim": "Bosentan, a lipophilic heteroaromatic drug, has an absolute oral bioavailability of 50% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Celecoxib, despite being highly lipophilic and poorly soluble, has an oral bioavailability of 22-40% in humans, showing that solubility limitations do not preclude F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Sildenafil has an absolute oral bioavailability of 40% in humans despite gut-wall metabolism, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute bioavailability measurements (vismodegib 31.8%, erlotinib 59-76%, bosentan 50%, sildenafil 40%, celecoxib 22-40%) consistently place F above the 20% threshold despite lipophilicity/solubility concerns; the physicochemical low prior is overridden by this experimental evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule.",
    "Bupropion records are internally conflicting (10% vs >80%) and were not used as decisive evidence.",
    "The exact impact of the query's N-oxide and very high logD on absorption is not directly covered by a single analogue, though several poorly soluble analogues still exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

